--

DROP TABLE IF EXISTS `flights`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `flights` (
  `flight_id` varchar(10) NOT NULL COMMENT '航班号',
  `airline` varchar(50) DEFAULT NULL COMMENT '航空公司',
  `departure_city` varchar(50) DEFAULT NULL COMMENT '出发城市',
  `arrival_city` varchar(50) DEFAULT NULL COMMENT '到达城市',
  `departure_time` datetime DEFAULT NULL COMMENT '起飞时间',
  `arrival_time` datetime DEFAULT NULL COMMENT '到达时间',
  `price` decimal(10,2) DEFAULT NULL COMMENT '票价',
  `capacity` int DEFAULT NULL COMMENT '总座位数',
  `booked_count` int DEFAULT NULL COMMENT '已订票数',
  `status` varchar(20) DEFAULT NULL COMMENT '航班状态',
  PRIMARY KEY (`flight_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

